// Simple CIDR (IPv4/IPv6) representation for ACLs.
#[derive(Clone, Debug)]
struct IpNet {
    kind: IpKind,
}

#[derive(Clone, Debug)]
enum IpKind {
    V4 { net: u32, mask: u32 },
    V6 { net: [u8; 16], bits: u8 },
}

fn parse_cidr(s: &str) -> Option<IpNet> {
    if let Some((ip, bits_str)) = s.split_once('/') {
        let bits: u8 = bits_str.parse().ok()?;
        if let Ok(v4) = ip.parse::<std::net::Ipv4Addr>() {
            if bits > 32 {
                return None;
            }
            let n = u32::from(v4);
            let mask = if bits == 0 {
                0
            } else {
                u32::MAX << (32 - bits)
            };
            return Some(IpNet {
                kind: IpKind::V4 {
                    net: n & mask,
                    mask,
                },
            });
        }
        if let Ok(v6) = ip.parse::<std::net::Ipv6Addr>() {
            if bits > 128 {
                return None;
            }
            let mut net = [0u8; 16];
            net.copy_from_slice(&v6.octets());
            let full_bytes = (bits / 8) as usize;
            let rem_bits = bits % 8;
            if full_bytes < 16 {
                if rem_bits == 0 {
                    for b in net.iter_mut().skip(full_bytes) {
                        *b = 0;
                    }
                } else {
                    for b in net.iter_mut().skip(full_bytes + 1) {
                        *b = 0;
                    }
                    let mask = 0xFFu8 << (8 - rem_bits);
                    net[full_bytes] &= mask;
                }
            }
            return Some(IpNet {
                kind: IpKind::V6 { net, bits },
            });
        }
    }
    None
}

fn parse_cidrs(list: &[String]) -> Vec<IpNet> {
    list.iter().filter_map(|s| parse_cidr(s)).collect()
}

fn cidr_contains(nets: &[IpNet], ip: std::net::IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => {
            let x = u32::from(v4);
            nets.iter().any(|n| match &n.kind {
                IpKind::V4 { net, mask } => (x & mask) == *net,
                _ => false,
            })
        }
        IpAddr::V6(v6) => {
            let x = v6.octets();
            nets.iter().any(|n| match &n.kind {
                IpKind::V6 { net, bits } => {
                    let full = (*bits / 8) as usize;
                    let rem = *bits % 8;
                    (full == 0 || x[..full] == net[..full])
                        && (rem == 0 || {
                            let mask = 0xFFu8 << (8 - rem);
                            (x[full] & mask) == (net[full] & mask)
                        })
                }
                _ => false,
            })
        }
    }
}

fn runtime_from_handshake(
    handshake: ActualSoranetHandshake,
) -> Result<Arc<SoranetHandshakeConfig>, Error> {
    let ActualSoranetHandshake {
        descriptor_commit,
        client_capabilities,
        relay_capabilities,
        trust_gossip,
        kem_id,
        sig_id,
        resume_hash,
        pow,
    } = handshake;

    let ActualSoranetPow {
        required,
        difficulty,
        max_future_skew,
        min_ticket_ttl,
        ticket_ttl,
        revocation_store_capacity,
        revocation_max_ttl,
        revocation_store_path,
        puzzle,
        signed_ticket_public_key,
    } = pow;

    let pow_params =
        PowParameters::try_new(difficulty, max_future_skew, min_ticket_ttl).map_err(|err| {
            Error::HandshakeSoranet(format!("invalid soranet PoW configuration: {err}"))
        })?;
    let puzzle_params = puzzle
        .map(|cfg| {
            puzzle::Parameters::try_new(
                cfg.memory_kib,
                cfg.time_cost,
                cfg.lanes,
                difficulty,
                max_future_skew,
                min_ticket_ttl,
            )
            .map_err(|err| {
                Error::HandshakeSoranet(format!("invalid soranet puzzle configuration: {err}"))
            })
        })
        .transpose()?;

    let signed_ticket_public_key = signed_ticket_public_key
        .map(|key| {
            let expected = MlDsaSuite::MlDsa44.public_key_len();
            if key.len() != expected {
                return Err(Error::HandshakeSoranet(format!(
                    "invalid soranet signed_ticket_public_key_hex: expected {expected} bytes (ML-DSA-44), got {}",
                    key.len()
                )));
            }
            Ok(key)
        })
        .transpose()?;

    let revocation_limits =
        TicketRevocationStoreLimits::new(revocation_store_capacity, revocation_max_ttl).map_err(
            |err| {
                Error::HandshakeSoranet(format!("invalid soranet revocation configuration: {err}"))
            },
        )?;
    let revocation_store = if required {
        TicketRevocationStore::load(
            revocation_store_path.as_ref(),
            revocation_limits,
            SystemTime::now(),
        )
        .map_err(|err| {
            Error::HandshakeSoranet(format!(
                "failed to load soranet revocation store at {}: {err}",
                revocation_store_path
            ))
        })?
    } else {
        // Production configuration fixes `required = true`. Programmatic test
        // configurations that disable admission must not create shared replay
        // state in the workspace.
        TicketRevocationStore::in_memory(revocation_limits).map_err(|err| {
            Error::HandshakeSoranet(format!("invalid soranet revocation configuration: {err}"))
        })?
    };
    let revocation_store = Some(Arc::new(Mutex::new(revocation_store)));

    let config = SoranetHandshakeConfig::new(
        descriptor_commit.into_value(),
        client_capabilities.into_value(),
        relay_capabilities.into_value(),
        trust_gossip,
        kem_id,
        sig_id,
        resume_hash.map(iroha_config::base::WithOrigin::into_value),
        required,
        pow_params,
        puzzle_params,
        ticket_ttl,
        signed_ticket_public_key,
        revocation_store,
        None,
    );
    Ok(Arc::new(config))
}

fn debug_packet_loss_should_drop(percent: u8, counter: &mut u64) -> bool {
    debug_assert!(percent <= 100);
    if percent == 0 {
        return false;
    }
    let current = *counter;
    *counter = counter.wrapping_add(1);
    if percent >= 100 {
        return true;
    }
    current.wrapping_mul(37).wrapping_add(17) % 100 < u64::from(percent)
}

fn relay_role_from_mode(mode: iroha_config::parameters::actual::RelayMode) -> RelayRole {
    match mode {
        iroha_config::parameters::actual::RelayMode::Hub => RelayRole::Hub,
        iroha_config::parameters::actual::RelayMode::Spoke => RelayRole::Spoke,
        iroha_config::parameters::actual::RelayMode::Disabled
        | iroha_config::parameters::actual::RelayMode::Assist => RelayRole::Disabled,
    }
}

