    fn accept_direct_targets<T: Pload>(
        handle: &NetworkBaseHandle<T, ChaCha20Poly1305>,
        targets: HashSet<PeerId>,
    ) {
        let _ = handle
            .reliable_direct_topology
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .reconcile(&targets, &handle.self_id);
    }

